#!/bin/sh
# include_api_docs.sh <doc dir>
#
# Unpacks docs/api.zip (the generated API reference) into <doc dir> -- the deploy
# tree's doc/ -- for the POSIX deploy scripts.
#
# docs/api.zip is NOT in git. It used to be, regenerated by hand for every bump and
# then again by a bot commit from release-build.yml, and it drifted (a correct
# version stamp over missing libraries; v2026.8.0's docs shipping as v2026.8.1's).
# Now release-build.yml's "Generate API Docs" job makes it and the build jobs
# download it as the `api-docs` artifact to docs/api.zip before they deploy; a
# Windows x64 deploy writes it there itself (code_doc64.cmd), and anyone else can
# make one with tools/cicd/gen_api_docs.sh.
#
# Missing file:
#   OBJECK_REQUIRE_API_DOCS=1  (the release build sets it)  -> fail, so a release can
#                               never ship without its docs
#   otherwise (CI, benchmarks, local builds)               -> say so and carry on; the
#                               deploy tree is complete except for doc/api
set -e

DEST="${1:?usage: include_api_docs.sh <doc dir>}"
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
ZIP="$ROOT/docs/api.zip"

if [ -f "$ZIP" ]; then
  unzip -q -o "$ZIP" -d "$DEST"
  exit 0
fi

if [ "${OBJECK_REQUIRE_API_DOCS:-}" = 1 ]; then
  echo "ERROR: $ZIP not found and OBJECK_REQUIRE_API_DOCS is set." >&2
  echo "       The release build downloads it from the api-docs artifact of its own run;" >&2
  echo "       locally, run tools/cicd/gen_api_docs.sh against this deploy tree." >&2
  exit 1
fi

echo "note: docs/api.zip not found -- the API reference is not included in this deploy tree" >&2
echo "      (generate it with tools/cicd/gen_api_docs.sh if you need it)" >&2
